def is_palindrome(number):
    num = str(number)
    return num == num[::-1]

def even_odd_palindrome(n):
    even_count, odd_count = 0, 0

    for i in range(1, n + 1):
        if is_palindrome(i) and (i % 2 == 0 or int(str(i)[-1]) != '5'): # Checking evenness excluding numbers ending with "5" which are not divisible by two.
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

